import { test } from "node:test";
import assert from "node:assert/strict";
import { start } from "./helpers.js";

test("stats for an unknown slug is 404 identical to the redirect route", async () => {
  const app = await start();
  const stats = await app.get("/stats/nope");
  const redirect = await app.get("/nope");
  assert.equal(stats.status, 404);
  assert.deepEqual(stats.body, { error: "not found" });
  assert.equal(stats.status, redirect.status);
  assert.deepEqual(stats.body, redirect.body);
  assert.equal(stats.headers.get("content-type"), redirect.headers.get("content-type"));
  await app.close();
});

test("stats for an existing slug is unchanged", async () => {
  const app = await start({ now: () => 42, randomSlug: () => "abc123" });
  await app.post("/links", { url: "https://example.com/x" });
  const res = await app.get("/stats/abc123");
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, { slug: "abc123", url: "https://example.com/x", clicks: 0, createdAt: 42 });
  await app.close();
});
